import{_ as e,c as i,o as r,ah as t}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/yilin/index.md","filePath":"ja/articles/yilin/index.md"}'),n={name:"ja/articles/yilin/index.md"};function l(o,a,s,d,c,p){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="焦氏易林" tabindex="-1">焦氏易林 <a class="header-anchor" href="#焦氏易林" aria-label="Permalink to “焦氏易林”">​</a></h1><p>焦氏易林（『易林』）は、漢代に成立したとされる詩体の占書で、西漢の易学者 <strong>焦延寿</strong> に帰されることが多い一方、作者については諸説あります。 『周易』六十四卦を土台にし、「本卦 → 之卦」の組み合わせで占辞を体系化しています。各卦が六十四に展開し、合計 <strong>64×64＝4096</strong> 条の短い詩句（多くは四言の韻文）として示されます。</p><h2 id="『周易』との物語" tabindex="-1">『周易』との物語 <a class="header-anchor" href="#『周易』との物語" aria-label="Permalink to “『周易』との物語”">​</a></h2><p>『周易』が卦象・卦爻辞という「枠組み」を与えるのに対し、焦氏易林はその意味をより具体的な<strong>象（イメージ）や情景</strong>として言い換え、占断の入口をつくるような役割を果たします。</p><h2 id="本アプリでの読み方" tabindex="-1">本アプリでの読み方 <a class="header-anchor" href="#本アプリでの読み方" aria-label="Permalink to “本アプリでの読み方”">​</a></h2><p>本アプリでは、占って得た「本卦 → 之卦」に対応する詩句を表示し、解釈の補助として使えます。</p><ol><li>詩のキーワード（人物・行為・場所・器物・吉凶語）を拾う</li><li>質問と現状に当てはめる</li><li>最後に卦象と動爻に戻って総合判断する</li></ol><h2 id="翻訳について" tabindex="-1">翻訳について <a class="header-anchor" href="#翻訳について" aria-label="Permalink to “翻訳について”">​</a></h2><p>英訳は中文を元にした直訳寄りの整理訳です。中文を優先し、英語は参考としてご利用ください。</p>',9)])])}const m=e(n,[["render",l]]);export{_ as __pageData,m as default};
